-- =============================================================================
-- Eden Apothecary: pre-1900 energetics sources for 25 more herbs (research
-- batch 4). DATA ONLY. Written 2026-09-15.
-- =============================================================================
-- Approved by the founder on 2026-09-15, as researched.
--
-- Writes public.herbs.energetics_citation for 25 herbs that had NULL
-- (3 where the old sources agree, 13 where they disagree and the page says so,
-- 4 with no pre-1900 source found at all). Same jsonb shape as batches 1 to 3,
-- carrying 'batch': 4.
--
-- This batch changes NO app value: every stored temperature and moisture in it
-- was judged clear, so the July 2026 ruling keeps all of them. Section 3 asserts
-- that nothing moved.
--
-- 5 herbs here found old readings but counted none of them (wrong species,
-- wrong plant part, a group statement, or the writer quoting someone else).
-- Each carries its own plain sentence saying why, free to read, per the founder
-- decision of 2026-09-15 that silence on such a page reads as 'nobody looked':
--   H026 Hawthorn:
--     'No pre-1900 source found for this exact plant. The one European writer gives astringency rather than a temperature, and the Chinese books describe a different hawthorn.'
--   H034 Linden:
--     'No pre-1900 source found for this part. The one old reading describes the bark and leaves, and this entry is about the flower.'
--   H043 Oat Straw:
--     'No pre-1900 source found for this part. Every old reading describes the grain, and this entry is about the green tops.'
--   H046 Peppermint:
--     'No pre-1900 source found for this exact plant. The old books speak of mint as a group, or describe spearmint or the Chinese mint, and peppermint is none of those.'
--   H048 Raspberry Leaf:
--     'No pre-1900 source found for this reading. One old writer only supposes it, by comparison to the bramble, and the other page is too damaged in the scan to read.'
--
-- BLAST RADIUS: production data on 25 of 300 herbs in public.herbs, one column,
-- energetics_citation, on rows where it is currently NULL. No temperature or
-- moisture changes, no schema change, no view change, no grant change, no RLS
-- change. The 69 legacy single-source citations and the 75 herbs already carrying
-- a batch object are untouched.
--
-- IDEMPOTENT. Verification aborts the whole transaction on any failure.
-- =============================================================================

begin;

-- -----------------------------------------------------------------------------
-- 0. Snapshot, so section 3 can prove no herb's energetics moved.
-- -----------------------------------------------------------------------------
create temporary table _energetics_before_b4 on commit drop as
  select herb_id, temperature, moisture from public.herbs;

-- -----------------------------------------------------------------------------
-- 1. The researched sources, staged then applied under one guard loop. The guard
--    refuses to overwrite anything that is not NULL and not already a batch
--    object.
-- -----------------------------------------------------------------------------
create temporary table _energetics_batch4 (
  herb_id text primary key,
  citation jsonb not null
) on commit drop;

-- H026 Hawthorn (2 sources, shown, none counted)
insert into _energetics_batch4 values ('H026', $j${"agreement_state": "none", "app_value": {"moisture": "Neutral", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Neutral (clear modern value; no pre-1900 source found)", "temperature": "stays Warm (clear modern value; no pre-1900 source found)"}, "batch": 4, "checked_no_reading": ["Culpeper 1653, the HAWTHORN chapter: a tree of Mars, seeds against the stone and dropsy, no degree of heat or dryness anywhere in the chapter", "Culpeper's catalogue: Hawthorn appears only in the College's list of leaves, and it is in none of his degree tables", "Salmon, Botanologia (1710): no hawthorn chapter; Oxyacantha appears only twice, in the end index", "Ibn al-Baytar, tr. Leclerc Vol. I, the article on oxyacantha: quotations from Dioscorides plus Leclerc's own footnote on which plant is meant, no first-hand degree", "Bencao Congxin (1757), Shennong Bencao Jing, Bhavaprakasha and Rajanighantu: no hawthorn entry found"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "No pre-1900 source found for this exact plant. The one European writer gives astringency rather than a temperature, and the Chinese books describe a different hawthorn.", "no_pre1900_source_found": false, "notes": ["No first-hand pre-1900 source found that gives this plant a temperature or a moisture.", "The stored parts are berry, leaf and flower."], "part_used": "Berry, Leaf, Flower", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value clear (a definite Neutral), so it stays Neutral.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. Astringency is not a temperature and not a moisture, so under the strict felt-heat rule this gives nothing to count. It is shown because it is the only thing Gerard says about the plant's temperature.", "assigns_moisture": null, "assigns_temperature": null, "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "The fruit of the Hawthorn tree is very astringent.", "gloss": "Gerard's whole Temperature note for the hawthorn: the fruit is very astringent.", "locator": "Book III, Chap. 24 'Of the Whitethorn, or Hawthorn Tree', The Temperature", "not_counted_why": "Astringency is not a temperature and not a moisture, so under the strict felt-heat rule this gives nothing to count. It is shown because it is the only thing Gerard says about the plant's temperature.", "note": "Astringency is not a temperature and not a moisture, so under the strict felt-heat rule this gives nothing to count. It is shown because it is the only thing Gerard says about the plant's temperature.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Shown for context. The Chinese shan zha is Crataegus pinnatifida and its kin, not the European Crataegus monogyna. Shown, not counted. Note also that the entry itself carries two readings, a cold one in the heading and Li Shizhen's own slightly warm one.", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "氣味酸冷無毒{{SKnotes|時珍曰酸甘微温生食多令人嘈煩易飢損齒}}", "gloss": "Chinese hawthorn (shan zha): sour, COLD, not toxic. Li Shizhen adds: sour, sweet, slightly WARM; eaten raw in quantity it causes gnawing hunger and harms the teeth.", "locator": "卷三十 果之二, 山樝 (with 赤爪子, 棠梂子), 氣味", "not_counted_why": "The Chinese shan zha is Crataegus pinnatifida and its kin, not the European Crataegus monogyna. Shown, not counted. Note also that the entry itself carries two readings, a cold one in the heading and Li Shizhen's own slightly warm one.", "note": "The Chinese shan zha is Crataegus pinnatifida and its kin, not the European Crataegus monogyna. Shown, not counted. Note also that the entry itself carries two readings, a cold one in the heading and Li Shizhen's own slightly warm one.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}], "sources_agree": false, "stored_before": {"moisture": "Neutral", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Neutral"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

