insert into _energetics_batch4 values ('H027', $j${"agreement_state": "agree", "app_value": {"moisture": "Dry", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; no pre-1900 source found)", "temperature": "stays Warm (clear modern value; old sources agree)"}, "batch": 4, "checked_no_reading": ["Dymock, Pharmacographia Indica Vol. III (1893), Ocimum sanctum: a long article on the worship of the plant and its uses, and 'According to the Raja Nirghanta, it removes cold, destroys intestinal worms and evil spirits, and alleviates vomiting', which reports another book and describes an action rather than a temperature", "Culpeper 1653: 'Bazil' appears in his degree tables (hot in the second degree, moist in the first), but his Bazil is the garden basil, a different species", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing: no Ocimum sanctum entry found"], "counted_readings": {"moisture": [], "temperature": [{"reading": "Warm", "source": "Bhavaprakasha (16th c.)"}, {"reading": "Warm", "source": "Rajanighantu (c. 15th c.)"}]}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored parts are leaf and flower; the Sanskrit verses describe the herb."], "part_used": "Leaf, Flower", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "ayurvedic", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "तुलसी कटुका तिक्ता हृद्योष्णा दाहपित्तकृत् । दीपनी कुष्ठकृच्छ्रास्रपार्श्वरुक्कफवातजित् ॥ शुक्ला कृष्णा च तुलसी गुणैस्तुल्या प्रकीर्त्तिता ॥", "gloss": "tulasi katuka tikta hrdya usna daha-pitta-krt: tulsi is pungent, bitter, good for the heart, HOT, and raises heat and pitta; it kindles digestion and conquers phlegm and wind. The white and the black tulsi are declared equal in their qualities.", "locator": "Pushpa varga 5.62-63", "not_counted_why": "", "note": "The verse names both kinds of tulsi and gives them one reading, so it counts for the plant. No moisture word (neither snigdha nor ruksha) is given.", "short": "Bhavaprakasha (16th c.)", "source": "Bhāvamiśra, Bhāvaprakāśa Nighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "https://sa.wikisource.org/wiki/भावप्रकाशः/पूर्वखण्डे_भावप्रकाशनिघण्टुः", "year": "16th century"}, {"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "ayurvedic", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "tulasī kaṭutiktoṣṇā surabhiḥ śleṣmavātajit / jantubhūtakrimiharā rucikṛd vātaśāntikṛt //", "gloss": "tulasi katu-tikta-usna: tulsi is pungent, bitter and HOT, fragrant, conquers phlegm and wind, destroys worms, whets the appetite and quiets wind.", "locator": "Rajanighantu 10.150", "not_counted_why": "", "note": "Temperature only; no moisture word.", "short": "Rajanighantu (c. 15th c.)", "source": "Narahari, Rājanighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "http://gretil.sub.uni-goettingen.de/gretil/corpustei/transformations/plaintext/sa_narahari-rAjanighaNTu.txt", "year": "c. 15th century"}, {"agreement": "Shown for context. Two reasons not to count it: Gerard is reporting Galen inside the sentence, and his basil is the garden basil Ocimum basilicum, not the Indian Ocimum tenuiflorum.", "assigns_moisture": "Moist", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Basil, as Galen teacheth, is hot in the second degree, but it hath adjoined with it a superfluous moisture, by reason whereof he doth not like that it should be taken inwardly", "gloss": "Garden basil is hot in the second degree with a superfluous moisture.", "locator": "Book II, Chap. 223 'Of Basil', The Temperature", "not_counted_why": "Two reasons not to count it: Gerard is reporting Galen inside the sentence, and his basil is the garden basil Ocimum basilicum, not the Indian Ocimum tenuiflorum.", "note": "Two reasons not to count it: Gerard is reporting Galen inside the sentence, and his basil is the garden basil Ocimum basilicum, not the Indian Ocimum tenuiflorum.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "second-hand-report", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Shown for context. Salmon gives his own judgement, so it is first-hand, but his common basil is Ocimum basilicum, a different species from the stored Ocimum tenuiflorum. Shown, not counted.", "assigns_moisture": "Moist", "assigns_temperature": "Cool", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Galen affirms it to be mode- er cold and moift: I judge it to be cold and moift in the firft Degree: it is Repercuflive and Difcutient", "gloss": "Galen calls common basil moderately cold and moist; Salmon judges it cold and moist in the first degree.", "locator": "Chap. XLVI 'Of Common BASIL', The Qualities (OCR near offset 494248; the heading at 494248 reads 'CHAP. XLVI. Of Common BASIL', and the word after 'mode-' is broken in the scan)", "not_counted_why": "Salmon gives his own judgement, so it is first-hand, but his common basil is Ocimum basilicum, a different species from the stored Ocimum tenuiflorum. Shown, not counted.", "note": "Salmon gives his own judgement, so it is first-hand, but his common basil is Ocimum basilicum, a different species from the stored Ocimum tenuiflorum. Shown, not counted.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": true, "stored_before": {"moisture": "Dry", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

-- H028 Hops (3 sources, SOURCES DISAGREE)
insert into _energetics_batch4 values ('H028', $j${"agreement_state": "disagree", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Cool (clear modern value; old sources disagree, shown on page)"}, "batch": 4, "checked_no_reading": ["Culpeper 1653, catalogue of simples, 'Lupulus. Hops': opening, cleansing, provoke urine, the young sprouts open stoppings of the liver and spleen, and purge choler, but no degree of heat or dryness", "Culpeper's degree tables: Hops appear only in the lists of herbs that heat the liver and the spleen, not in the degree lists", "Shennong Bencao Jing, Bencao Congxin, Bhavaprakasha, Rajanighantu: no hop entry found"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Gerard (1633)"}, {"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Warm", "source": "Salmon (1710)"}]}, "disagreement_text": "On temperature, Gerard (1633) and Salmon (1710) read it as warm. The app keeps cool, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the strobile, which the old books call the flower or the head of the hop."], "part_used": "Strobiles (Cone)", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "The flowers of the hop are hot and dry in the second degree: they fill and stuff the head, and hurt the same with their strong smell. Of the same temperature also are the leaves themselves, which do likewise open and cleanse.", "gloss": "The hop flowers are hot and dry in the second degree, and so are the leaves.", "locator": "Book III, Chap. 325 'Of Hops', The Temperature", "not_counted_why": "", "note": "The reading is given for the flower, which is the stored part.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "VII. The Qualities. They are hot and dry in the third degree, Inciding , Apetitive, Abfterfive , Sub- aftringent, Digeftive, Difcuffive, and Diuretick", "gloss": "Hops are hot and dry in the third degree.", "locator": "Chapter 'Of HOPS', The Qualities (OCR at offset 2975394; the running head on the page reads Chap. 273, and the paragraph just before is about gathering the hops in August)", "not_counted_why": "", "note": "", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}, {"agreement": "Shown for context. The Chinese lu cao is Humulus scandens, the Japanese hop, not Humulus lupulus. Shown, not counted.", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "氣味甘苦寒無毒主治勒草主瘀血止精益盛氣{{SKnotes|别錄}}葎草主五淋利小便止水痢除瘧虚熱渴", "gloss": "Lu cao: sweet, bitter, COLD, not toxic. For the five kinds of strangury, promotes urine, stops watery dysentery, clears the empty heat and thirst of malaria.", "locator": "卷十八下 草之七, 葎草 (勒草)", "not_counted_why": "The Chinese lu cao is Humulus scandens, the Japanese hop, not Humulus lupulus. Shown, not counted.", "note": "The Chinese lu cao is Humulus scandens, the Japanese hop, not Humulus lupulus. Shown, not counted.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H029 Horsetail (4 sources, sources agree)
insert into _energetics_batch4 values ('H029', $j${"agreement_state": "agree", "app_value": {"moisture": "Dry", "temperature": "Neutral"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Neutral (clear modern value; no pre-1900 source found)"}, "batch": 4, "checked_no_reading": ["Culpeper 1653, the HORSETAIL chapter: wound and flux virtues at length, no degree", "Bhavaprakasha, Rajanighantu, Shennong Bencao Jing, Bencao Congxin: no horsetail entry found", "Rafinesque, Medical Flora Vol. II (1830), EQUISETUM: 'astringent and diuretic, used in hematuria, gonorrhea, phthisis', no temperature or moisture"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Culpeper (1653)"}], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored plant is the common field horsetail, Equisetum arvense. The old English books treat 'horsetail' as one herb with several kinds and do not separate the species the way modern botany does; Salmon is the exception and names his kinds, which is why his reading is set aside below."], "part_used": "Aerial Parts", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Neutral), so it stays Neutral. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": null, "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": false, "excerpt": "Cauda Equina. Horse-tail; is of a binding drying quality, cures wounds, and is an admirable remedy for sinews that are shrunk: it is a sure remedy for bleeding at the nose, or by wound, stops the menses, fluxes, ulcers in the reins and bladder, coughs, ulcers in the lungs, difficulty of breathing.", "gloss": "Horsetail is of a binding, drying quality.", "locator": "Catalogue of simples, Herbs, 'Cauda Equina' (Gutenberg #49513, offset ~855514)", "not_counted_why": "", "note": "Moisture only. Culpeper gives horsetail no degree of heat or cold, here or in his degree tables.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Shown for context. Gerard is reporting Galen inside the sentence, so it is not counted.", "assigns_moisture": "Dry", "assigns_temperature": null, "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Horsetail, as Galen saith, hath a binding faculty, with some bitterness, and therefore it doth mightily dry, and that without biting.", "gloss": "Horsetail binds and dries mightily.", "locator": "Book II, Chap. 458 'Of Horsetail, or Shavegrass', The Temperature", "not_counted_why": "Gerard is reporting Galen inside the sentence, so it is not counted.", "note": "Gerard is reporting Galen inside the sentence, so it is not counted.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "second-hand-report", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Shown for context. Salmon divides the horsetails into three chapters and this one is the marsh or water horsetail, Equisetum palustre and its kin, not the stored Equisetum arvense. His Chap. 380 on meadow horsetail refers its qualities back to this chapter. Shown, not counted.", "assigns_moisture": "Dry", "assigns_temperature": "Neutral", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "XII. The Qualities, Tt is temperate in refpect to heat or coldnefS, and dry in the third degree, it has fome pitternefS, and mightily dries withcut biting", "gloss": "Marsh or water horsetail is temperate as to heat and cold, and dry in the third degree.", "locator": "Chapter 'Of HORSETAIL Marsh or Water', The Qualities (OCR at offset 3022068; the running head reads Chap. 379, and Salmon's own Kinds paragraph says the marsh or water horsetail is the one 'of which in this Chapter', the meadow horsetail being Chap. 380 and the naked horsetail Chap. 381)", "not_counted_why": "Salmon divides the horsetails into three chapters and this one is the marsh or water horsetail, Equisetum palustre and its kin, not the stored Equisetum arvense. His Chap. 380 on meadow horsetail refers its qualities back to this chapter. Shown, not counted.", "note": "Salmon divides the horsetails into three chapters and this one is the marsh or water horsetail, Equisetum palustre and its kin, not the stored Equisetum arvense. His Chap. 380 on meadow horsetail refers its qualities back to this chapter. Shown, not counted.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}, {"agreement": "Shown for context. The Chinese mu zei is Equisetum hyemale, the rough horsetail, not Equisetum arvense. Shown, not counted.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "氣味甘微苦無毒}}{{SKnotes|時珍曰温}}主治目疾退翳膜消積塊益肝膽療腸風止痢", "gloss": "Mu zei: sweet, slightly bitter, not toxic; Li Shizhen says WARM. For eye disease, clears films from the eye, disperses lumps, benefits liver and gall.", "locator": "卷十五 草之四, 木賊, 氣味", "not_counted_why": "The Chinese mu zei is Equisetum hyemale, the rough horsetail, not Equisetum arvense. Shown, not counted.", "note": "The Chinese mu zei is Equisetum hyemale, the rough horsetail, not Equisetum arvense. Shown, not counted.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}], "sources_agree": true, "stored_before": {"moisture": "Dry", "temperature": "Neutral"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Neutral"}}}$j$::jsonb);

-- H030 Kava (0 sources, no qualifying source)
insert into _energetics_batch4 values ('H030', $j${"agreement_state": "none", "app_value": {"moisture": "Dry", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; no pre-1900 source found)", "temperature": "stays Warm (clear modern value; no pre-1900 source found)"}, "batch": 4, "checked_no_reading": ["Ainslie, Materia Indica Vol. II (1826), under Piper dichotomum: 'The piper dichotomum (Rottler) must not be confounded with the piper methysticum of the Friendly Islands, the stem of which is dichotomous, and the root yields, in Otaheite, the intoxicating liquor called ava or hava.' That is the only pre-1900 mention of the plant in any text downloaded for this batch, and it gives no quality", "Searched every downloaded corpus for 'methysticum', 'kava', 'kawa' and 'ava': no other pre-1900 hit", "Culpeper 1653, Gerard 1633, Salmon 1710: no chapter (the plant is Polynesian and none of the three knew it)", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu, Dymock Vols. I-III, Dutt 1877, Ibn al-Baytar (Leclerc Vols. I and II), Porter Smith 1871, Schopf 1787, Rafinesque 1828-30: no entry"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": true, "notes": ["No pre-1900 source found that gives this plant a temperature or a moisture."], "part_used": "Root", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

-- H031 Lavender (3 sources, SOURCES DISAGREE)
insert into _energetics_batch4 values ('H031', $j${"agreement_state": "disagree", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Cool (clear modern value; old sources disagree, shown on page)"}, "batch": 4, "checked_no_reading": ["Gerard, Book II Chap. 180 'Of French Lavender, or Stickadove': a different species (Lavandula stoechas) and the reading there is Gerard reporting Galen", "Dymock, Pharmacographia Indica: Lavandula is mentioned only in passing and carries no thermal quality", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no lavender entry found"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Gerard (1633)"}, {"reading": "Dry", "source": "Culpeper (1653)"}, {"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Warm", "source": "Culpeper (1653)"}, {"reading": "Warm", "source": "Salmon (1710)"}]}, "disagreement_text": "On temperature, Gerard (1633), Culpeper (1653) and Salmon (1710) read it as warm. The app keeps cool, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the flower. Gerard, Culpeper and Salmon all give the degree for the herb as a whole."], "part_used": "Flower", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Lavender is hot and dry, and that in the third degree", "gloss": "Lavender is hot and dry in the third degree.", "locator": "Book II, Chap. 179 'Of Lavender Spike', The Temperature", "not_counted_why": "", "note": "", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Lavendula. Lavender: Hot and dry in the third degree: the temples and forehead bathed with the juice of it; as also the smell of the herb helps swoonings, catalepsis, falling-sickness; also in his degree tables, 'In the third degree. … Lavender' among the hot herbs and 'Dry in the third degree. … Lavender'", "gloss": "Lavender is hot and dry in the third degree.", "locator": "Catalogue of simples, Herbs, 'Lavendula' (Gutenberg #49513, offset ~874892); Culpeper's degree tables, 'Herbs' (Gutenberg #49513, offset ~950000)", "not_counted_why": "", "note": "", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "X. The Qualities. Layender is hot and dry in the third Degree: it is Abfterfive, Aperitive, Aftringent, Difcuffive, Diuretick and Incifive.", "gloss": "Lavender is hot and dry in the third degree.", "locator": "Chapter 'Of LAVENDER', The Qualities (OCR at offset 3369368; the scan reads 'Layender', and the chapter number on the page is not legible)", "not_counted_why": "", "note": "", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H032 Lemon Balm (3 sources, SOURCES DISAGREE)
insert into _energetics_batch4 values ('H032', $j${"agreement_state": "disagree", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Cool (clear modern value; old sources disagree, shown on page)"}, "batch": 4, "checked_no_reading": ["Schopf, Materia Medica Americana (1787): the Melissa entries are Melissa pulegioides, the American pennyroyal, a different plant", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no Melissa officinalis entry found"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Culpeper (1653)"}, {"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Warm", "source": "Culpeper (1653)"}, {"reading": "Warm", "source": "Salmon (1710)"}]}, "disagreement_text": "On temperature, Culpeper (1653) and Salmon (1710) read it as warm. The app keeps cool, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the leaf; all three English writers give the degree for the herb."], "part_used": "Leaf", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Mellissa. Balm. Hot and dry: outwardly mixed with salt and applied to the neck, helps the King's-evil … inwardly it is an excellent remedy for a cold and moist stomach, cheers the heart, refreshes the mind … Galen, Avicenna.; and in his degree tables, 'In the second. … Bawm' among the hot herbs and 'Dry in the second degree. … Bawm'", "gloss": "Balm is hot and dry, and by his tables hot and dry in the second degree.", "locator": "Catalogue of simples, Herbs, 'Mellissa' (Gutenberg #49513, offset ~880737); Culpeper's degree tables, 'Herbs' (Gutenberg #49513, offset ~950000)", "not_counted_why": "", "note": "The entry ends with the authorities 'Galen, Avicenna' in italics. Following the batch 3 default, a name at the END of an entry is treated as Culpeper's reference rather than as a report, so this is counted.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Shown for context. Gerard names Avicenna inside the sentence, so this is a report and is not counted.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Balm is of temperature hot and dry in the second degree, as Avicenna saith: Galen saith it is like Horehound in faculty.", "gloss": "Balm is hot and dry in the second degree.", "locator": "Book II, Chap. 230 'Of Balm', The Temperature", "not_counted_why": "Gerard names Avicenna inside the sentence, so this is a report and is not counted.", "note": "Gerard names Avicenna inside the sentence, so this is a report and is not counted.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "second-hand-report", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "VII. The Qualities. They are both hot and dry in the fecond degree : they are Cephalick, Neurotick, Cardiack, and fomething Hytterick", "gloss": "Garden balm and wild balm are both hot and dry in the second degree.", "locator": "Chapter 'Of BALM Garden and Wild', The Qualities (OCR at offset 538038; the running head reads Chap. 53)", "not_counted_why": "", "note": "'They are both' names the two kinds of balm in his chapter, so by the rule for a sentence naming two kinds it counts for the garden balm, which is the stored plant.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H033 Licorice (7 sources, SOURCES DISAGREE)
insert into _energetics_batch4 values ('H033', $j${"agreement_state": "disagree", "app_value": {"moisture": "Moist", "temperature": "Neutral"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moist (clear modern value; old sources disagree, shown on page)", "temperature": "stays Neutral (clear modern value; old sources disagree, shown on page)"}, "batch": 4, "checked_no_reading": ["Culpeper 1653: the LIQUORICE chapter gives virtues for coughs and hoarseness only, and liquorice appears in none of his degree tables", "Dymock, Pharmacographia Indica: Glycyrrhiza is mentioned only in passing", "Schopf 1787: the only Glycyrrhiza mention is a comparison ('Glycyrrhizae odore') in the locust-tree entry"], "counted_readings": {"moisture": [{"reading": "Moist", "source": "Gerard (1633)"}, {"reading": "Neutral", "source": "Salmon (1710)"}, {"reading": "Moist", "source": "Bhavaprakasha (16th c.)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Neutral", "source": "Salmon (1710)"}, {"reading": "Cool", "source": "Bhavaprakasha (16th c.)"}, {"reading": "Cool", "source": "Rajanighantu (c. 15th c.)"}]}, "disagreement_text": "On temperature, the old sources disagree: Gerard (1633) reads it as warm; Salmon (1710) reads it as neutral; Bhavaprakasha (16th c.) and Rajanighantu (c. 15th c.) read it as cool. The app keeps neutral, the modern reading of what the herb does in the body; the old readings are shown here but do not change it. On moisture, the old sources disagree: Gerard (1633) and Bhavaprakasha (16th c.) read it as moist; Salmon (1710) reads it as neutral. The app keeps moist, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the root, which is the part every source below is talking about."], "part_used": "Root", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Neutral), so it stays Neutral. Moisture: stored value clear (a definite Moist), so it stays Moist.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source warm, app neutral); agrees with the app moisture (moist).", "assigns_moisture": "Moist", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "For as much as the root of the common Liquorice is sweet, it is also temperately hot and moist; notwithstanding the bark thereof is something bitter and hot, but this must be scraped away; the fresh root when it is full of juice doth moisten more than the dry.", "gloss": "The root of the common liquorice is temperately hot and moist.", "locator": "Book III, Chap. 12 'Of Liquorice', The Temperature", "not_counted_why": "", "note": "Read as warm because Gerard writes 'temperately hot', but in the same paragraph he says liquorice comes 'nearest of all to a mean temperature', so his reading sits between warm and neutral. The first half of that paragraph is Gerard reporting Galen on Dioscorides' liquorice and is not used; the sentence quoted here is his own, about the common liquorice.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: agrees with the app temperature (neutral); differs from the app moisture (source neutral, app moist).", "assigns_moisture": "Neutral", "assigns_temperature": "Neutral", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "IX. The Qualities. Liquorice (the Root which is chiefly ufed in Phyfick) is temperate in refpe&t to Heat, Coldnef, Drynefs or Moifture : if there is any thing of Intemperature in ir, it is fomething hot and moift.", "gloss": "Liquorice root is temperate in heat, cold, dryness and moisture; if it leans anywhere it is somewhat hot and moist.", "locator": "Chapter 'Of LIQUORICE', The Qualities (OCR at offset 3566174; the chapter number on the page is not legible)", "not_counted_why": "", "note": "Counted as Neutral on both axes, because that is what he states; his second clause about a slight leaning to hot and moist is shown but is not a degree.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}, {"agreement": "Counted: differs from the app temperature (source cool, app neutral); agrees with the app moisture (moist).", "assigns_moisture": "Moist", "assigns_temperature": "Cool", "corpus": "ayurvedic", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "यष्टी हिमा गुरुः स्वाद्वी चक्षुष्या बलवर्णकृत् । सुस्निग्धा शुक्रला केश्या स्वर्या पित्तानिलास्रजित् ॥", "gloss": "yasti hima guruh svadvi … susnigdha: liquorice is COLD, heavy, sweet, good for the eyes, gives strength and complexion, is very UNCTUOUS, good for the seed, the hair and the voice.", "locator": "Haritakyadi varga 1.145-146", "not_counted_why": "", "note": "Susnigdha, very unctuous, counts as Moist under the moisture rule.", "short": "Bhavaprakasha (16th c.)", "source": "Bhāvamiśra, Bhāvaprakāśa Nighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "https://sa.wikisource.org/wiki/भावप्रकाशः/पूर्वखण्डे_भावप्रकाशनिघण्टुः", "year": "16th century"}, {"agreement": "Counted: differs from the app temperature (source cool, app neutral).", "assigns_moisture": null, "assigns_temperature": "Cool", "corpus": "ayurvedic", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "madhuraṃ yaṣṭimadhukaṃ kiṃcit tiktaṃ ca śītalam / cakṣuṣyaṃ pittahṛd rucyaṃ śoṣatṛṣṇāvraṇāpaham //", "gloss": "yastimadhuka is sweet, a little bitter and COLD, good for the eyes, removes bile, whets the appetite, and takes away wasting, thirst and sores.", "locator": "Rajanighantu 5.145", "not_counted_why": "", "note": "Temperature only; no moisture word in the verse.", "short": "Rajanighantu (c. 15th c.)", "source": "Narahari, Rājanighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "http://gretil.sub.uni-goettingen.de/gretil/corpustei/transformations/plaintext/sa_narahari-rAjanighaNTu.txt", "year": "c. 15th century"}, {"agreement": "Shown for context. Chinese gan cao is drawn chiefly from Glycyrrhiza uralensis rather than the stored Glycyrrhiza glabra, so under the batch 3 default for a drug that several species make it is shown and not counted. See the flagged section.", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "==甘草==味甘，平。主五臟六腑寒熱邪氣，堅筋骨，長肌肉，倍力，金創，解毒。久服，輕身、延年", "gloss": "Gan cao: sweet, NEUTRAL (ping). For cold and hot evil qi in the five viscera and six bowels, hardens sinew and bone, grows flesh, doubles strength, for wounds, resolves toxin.", "locator": "上經 (upper class), 甘草", "not_counted_why": "Chinese gan cao is drawn chiefly from Glycyrrhiza uralensis rather than the stored Glycyrrhiza glabra, so under the batch 3 default for a drug that several species make it is shown and not counted. See the flagged section.", "note": "Chinese gan cao is drawn chiefly from Glycyrrhiza uralensis rather than the stored Glycyrrhiza glabra, so under the batch 3 default for a drug that several species make it is shown and not counted. See the flagged section.", "short": "Shennong Bencao Jing (c. 200 CE)", "source": "神農本草經 (Shennong Bencao Jing, c. 200 CE), Sun Xingyan recension", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/神農本草經_(孫星衍)", "year": "c. 200 CE (recension 1799)"}, {"agreement": "Shown for context. Two reasons not to count it: the heading repeats the Shennong reading word for word, so it would count once and be credited to Shennong, and the species question above applies as well.", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "氣味甘平無毒}}{{SKnotes|寇宗奭曰生則㣲凉味不佳炙則温王好古曰氣薄味厚升而浮陽也}}", "gloss": "Root: sweet, NEUTRAL, not toxic. Kou Zongshi adds that raw it is slightly cool and poor in taste, roasted it is warm.", "locator": "卷十二上 草之一, 甘草, 氣味", "not_counted_why": "Two reasons not to count it: the heading repeats the Shennong reading word for word, so it would count once and be credited to Shennong, and the species question above applies as well.", "note": "Two reasons not to count it: the heading repeats the Shennong reading word for word, so it would count once and be credited to Shennong, and the species question above applies as well.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}, {"agreement": "Shown for context. Same species question. Worth showing anyway because it separates the raw root (neutral) from the roasted root (warm), which is the same distinction the Bencao Gangmu note makes.", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "甘草有補有瀉、能表能里、可升可降、生陰血。味甘。生用氣平。補脾胃不足。而瀉心火。炙用氣溫。補三焦元氣。而散表寒。", "gloss": "Gan cao supplements and drains, reaches the exterior and the interior, rises and falls. Taste sweet. Used RAW its qi is NEUTRAL, supplementing spleen and stomach and draining heart fire; used ROASTED its qi is WARM.", "locator": "卷三 草部, 甘草", "not_counted_why": "Same species question. Worth showing anyway because it separates the raw root (neutral) from the roasted root (warm), which is the same distinction the Bencao Gangmu note makes.", "note": "Same species question. Worth showing anyway because it separates the raw root (neutral) from the roasted root (warm), which is the same distinction the Bencao Gangmu note makes.", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}], "sources_agree": false, "stored_before": {"moisture": "Moist", "temperature": "Neutral"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist"}, "temperature": {"status": "clear", "why": "a definite Neutral"}}}$j$::jsonb);

-- H034 Linden (1 source, shown, none counted)
insert into _energetics_batch4 values ('H034', $j${"agreement_state": "none", "app_value": {"moisture": "Moist", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moist (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; no pre-1900 source found)"}, "batch": 4, "checked_no_reading": ["Culpeper 1653: 'Lime tree leaves' appear in the College's list of leaves and 'Lime tree' in the list of barks, with no degree, and there is no Tilia entry in his catalogue or his degree tables", "Salmon, Botanologia (1710): no lime-tree chapter; Tilia appears only in the end index", "Schopf, Materia Medica Americana (1787): the Tilia entry is an American species and gives 'vis: refrigerans', a virtue rather than a degree", "Porter Smith 1871: his Tilia entries are Chinese species", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no Tilia europaea entry found"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "No pre-1900 source found for this part. The one old reading describes the bark and leaves, and this entry is about the flower.", "no_pre1900_source_found": false, "notes": ["No first-hand pre-1900 source found that gives the flower a temperature or a moisture.", "The stored parts are the flower and its bract. Gerard's only temperature statement is for the bark and the leaves, which is why it is not counted."], "part_used": "Flower, Bract", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Moist), so it stays Moist.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. Bark and leaves, not the flower. Gerard does mention the flowers in his Virtues, against headache from a cold cause, but gives them no temperature. Shown, not counted.", "assigns_moisture": "Dry", "assigns_temperature": "Neutral", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "The bark and leaves of the Linden or Lime tree, are of a temperate heat, somewhat drying and astringent.", "gloss": "The bark and leaves of the lime tree are of a temperate heat and somewhat drying.", "locator": "Book III, Chap. 117 'Of the Lime or Linden Tree', The Temperature", "not_counted_why": "Bark and leaves, not the flower. Gerard does mention the flowers in his Virtues, against headache from a cold cause, but gives them no temperature. Shown, not counted.", "note": "Bark and leaves, not the flower. Gerard does mention the flowers in his Virtues, against headache from a cold cause, but gives them no temperature. Shown, not counted.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}], "sources_agree": false, "stored_before": {"moisture": "Moist", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

