tral"}}}$j$::jsonb);

-- H036 Marshmallow (4 sources, SOURCES DISAGREE)
insert into _energetics_batch4 values ('H036', $j${"agreement_state": "disagree", "app_value": {"moisture": "Moist", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moist (clear modern value; old sources disagree, shown on page)", "temperature": "stays Cool (clear modern value; old sources disagree, shown on page)"}, "batch": 4, "checked_no_reading": ["Culpeper's MALLOWS chapter: virtues at length, no degree for the marsh mallow separately", "Dymock, Pharmacographia Indica Vol. I, Althaea: no thermal quality", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no Althaea officinalis entry found"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Culpeper (1653)"}, {"reading": "Moist", "source": "Salmon (1710)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Warm", "source": "Culpeper (1653)"}, {"reading": "Neutral", "source": "Salmon (1710)"}]}, "disagreement_text": "On temperature, the old sources disagree: Gerard (1633) and Culpeper (1653) read it as warm; Salmon (1710) reads it as neutral. The app keeps cool, the modern reading of what the herb does in the body; the old readings are shown here but do not change it. On moisture, the old sources disagree: Culpeper (1653) reads it as dry; Salmon (1710) reads it as moist. The app keeps moist, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored parts are root and leaf, and the readings below are for the plant or for the root, so they qualify."], "part_used": "Root, Leaf", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Moist), so it stays Moist.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source warm, app cool).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "Marsh Mallow is moderately hot, but drier than the other Mallows: the roots and seeds hereof are more dry, and of thinner parts, as Galen writeth; and likewise of a digesting, softening or mollifying nature.", "gloss": "Marsh mallow is moderately hot, and drier than the other mallows.", "locator": "Book II, Chap. 353 'Of Marsh Mallow', The Temperature", "not_counted_why": "", "note": "Temperature counted. The moisture is given only as a comparison with the other mallows, with no degree of its own, so it is shown but not counted. The clause about the roots and seeds is Gerard reporting Galen.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool); differs from the app moisture (source dry, app moist).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Althæa, &c. Marsh-Mallows. Are moderately hot and drier than other Mallows; they help digestion, and mitigate pain, ease the pains of the stone, and in the sides.; and in his degree tables, 'Intemperate and hot in the first degree, are … Marsh-mallows' and 'Herbs dry in the first degree. … Marsh-mallows'", "gloss": "Marsh mallows are moderately hot and drier than other mallows; by his tables, hot in the first degree and dry in the first degree.", "locator": "Catalogue of simples, Herbs, 'Althæa' (Gutenberg #49513, offset ~841848); Culpeper's degree tables, 'Herbs' (Gutenberg #49513, offset ~950000)", "not_counted_why": "", "note": "", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: differs from the app temperature (source neutral, app cool); agrees with the app moisture (moist).", "assigns_moisture": "Moist", "assigns_temperature": "Neutral", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "X. The Qualities, Specification, Preparations, Virtues, and Ufes ot thefe, are the fame with thofe of the Common Mallow in the laft Chapter, faving that the firlt Althea, ot Common Marfh-Mallow in this Chapter, is of more than double Virtue to any of them; and in the last chapter, of the common mallow: 'XIV. The Qualities. Thefe Plants are all temperate in refpett of Heat and Cold; and moift in the firft Degree.'", "gloss": "Salmon refers the qualities of marsh mallow to those of the common mallow, which he calls temperate in heat and cold and moist in the first degree.", "locator": "Chap. CCCCLXVI 'Of MALLOW Marsh' (the chapter that follows CHAP. CCCCLXV 'Of MALLOW Common' and precedes CHAP. CCCCLXVII 'Of MALLOW Vervain'), The Qualities at OCR offset 3723004, where the scan has broken up the section heading itself; and Chap. CCCCLXV 'Of MALLOW Common', The Qualities at offset 3707352", "not_counted_why": "", "note": "A reading given by cross-reference, which counts under the rule used for Gerard on lady's mantle.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}, {"agreement": "Shown for context. Ibn al-Baytar's article is built from quotations, and this sentence stands between the names of Razès and Avicenna, so it is a report and not counted. Leclerc separates each authority with a dash; the dashes are left out of the quotation above because this document uses none.", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "unani", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Galien, livre VI. Dioscorides. Razès. La guimauve a une chaleur tempérée. Avicenne. Elle calme l'irritation et l'intumescence des paupières, est utile contre la toux, facilite l'expectoration", "gloss": "In Ibn al-Baytar's article on khitmi (marshmallow): the marshmallow has a temperate heat.", "locator": "Vol. II, no. 808 'Khitmi, Guimauve', p. 36", "not_counted_why": "Ibn al-Baytar's article is built from quotations, and this sentence stands between the names of Razès and Avicenna, so it is a report and not counted. Leclerc separates each authority with a dash; the dashes are left out of the quotation above because this document uses none.", "note": "Ibn al-Baytar's article is built from quotations, and this sentence stands between the names of Razès and Avicenna, so it is a report and not counted. Leclerc separates each authority with a dash; the dashes are left out of the quotation above because this document uses none.", "short": "Ibn al-Baytar, tr. Leclerc II (1881)", "source": "Ibn al-Baytar, Traité des simples, tr. Lucien Leclerc, Vol. II (Notices et extraits des manuscrits, t. 25, pt. 1; title page dated M DCCC LXXXI)", "tier": "second-hand-report", "tradition": "Unani (Arabic)", "url": "https://archive.org/download/NoticesEtExtraitsDesMss25P1/Notices_et_extraits_des_mss_25_p1_djvu.txt", "year": "1881"}], "sources_agree": false, "stored_before": {"moisture": "Moist", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H037 Meadowsweet (2 sources, SOURCES DISAGREE)
