-- H038 Milk Thistle (3 sources, SOURCES DISAGREE)
insert into _energetics_batch4 values ('H038', $j${"agreement_state": "disagree", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Cool (clear modern value; old sources disagree, shown on page)"}, "batch": 4, "checked_no_reading": ["Culpeper 1653: no 'Carduus Mariae' entry in the catalogue of simples; Lady's Thistle appears otherwise only in the list of herbs that heat the liver", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no Silybum marianum entry found"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Culpeper (1653)"}, {"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Warm", "source": "Culpeper (1653)"}, {"reading": "Warm", "source": "Salmon (1710)"}]}, "disagreement_text": "On temperature, Culpeper (1653) and Salmon (1710) read it as warm. The app keeps cool, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the seed. Culpeper and Salmon give their degree for the plant as a whole rather than for another part, so both are counted; Gerard's only degree is for the seed but he is reporting Galen."], "part_used": "Seed", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Intemperate and hot in the first degree, are Agrimony, Marsh-mallows, Goose-grass or Cleavers, Distaff Thistle, Borrage, Bugloss, or Lady's Thistles, Avens … Herbs dry in the first degree. Agrimony, Marsh-mallows, Cleavers, Burdocks, Shepherds-purse, our Lady's Thistle, Chervil, Chamomel", "gloss": "Our Lady's Thistle is hot in the first degree and dry in the first degree.", "locator": "Culpeper's degree tables, 'Herbs' (Gutenberg #49513, offset ~950000)", "not_counted_why": "", "note": "The dry list reads 'our Lady's Thistle' and is unambiguous. In the hot list the Gutenberg text reads 'Borrage, Bugloss, or Lady's Thistles', where 'or' is almost certainly the scanner's reading of 'our'; the item is reported as it stands rather than corrected.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "VII. The Qualities. The Milky Thiftle is hot and dry in the firlt Degree, Aperitive, Attingent, Svomatick, Sudorifick and Alexipharmick.", "gloss": "The milky thistle is hot and dry in the first degree.", "locator": "Chapter 'Of THISTLE Milky, OR, Ladies Thistle', The Qualities (OCR at offset 6009422; the chapter number on the page is not legible)", "not_counted_why": "", "note": "", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}, {"agreement": "Shown for context. Two reasons not to count it: every statement in the section is credited to Galen or Dioscorides inside the sentence, and the plant is called Spina alba, which Gerard himself only says 'is thought to be' the same as Our Lady's Thistle.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Galen writeth, that the roots of Spina alba do dry and moderately bind … The seed thereof is of a thin essence and hot faculty, therefore he saith that it is good for those that be troubled with cramps.", "gloss": "Galen is reported as saying the roots dry and bind and the seed is of a hot faculty.", "locator": "Book II, Chap. 477 'Of Our Lady's Thistle', The Temperature and Virtues", "not_counted_why": "Two reasons not to count it: every statement in the section is credited to Galen or Dioscorides inside the sentence, and the plant is called Spina alba, which Gerard himself only says 'is thought to be' the same as Our Lady's Thistle.", "note": "Two reasons not to count it: every statement in the section is credited to Galen or Dioscorides inside the sentence, and the plant is called Spina alba, which Gerard himself only says 'is thought to be' the same as Our Lady's Thistle.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "second-hand-report", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

