insert into _energetics_batch4 values ('H039', $j${"agreement_state": "disagree", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Cool (clear modern value; old sources disagree, shown on page)"}, "batch": 4, "checked_no_reading": ["Culpeper 1653, the MOTHERWORT chapter: 'It is of good use to warm and dry up the cold humours', which is an action rather than a degree, and there is no Cardiaca entry in his catalogue or in his degree tables", "Shennong Bencao Jing, Bencao Congxin, Bhavaprakasha, Rajanighantu: no Leonurus cardiaca entry found"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Gerard (1633)"}, {"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Warm", "source": "Salmon (1710)"}]}, "disagreement_text": "On temperature, Gerard (1633) and Salmon (1710) read it as warm. The app keeps cool, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the aerial herb, which is what Gerard and Salmon describe."], "part_used": "Aerial Parts", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Motherwort is hot and dry in the second degree, by reason of the cleansing and binding quality that it hath.", "gloss": "Motherwort is hot and dry in the second degree.", "locator": "Book II, Chap. 237 'Of Motherwort', The Temperature", "not_counted_why": "", "note": "", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "VII. The Qualiti[es] … is hot and dty in the … fecond Degree, Abft[erfive], Vulnerary, Cardia[ck] … and Hyfteric[k]", "gloss": "Motherwort is hot and dry in the second degree.", "locator": "Chapter 'Of MOTHER-WORT', The Qualities (OCR near offset 4002700; the running head inside the passage reads Chap. 503. The two columns of the page are interleaved in the scan, so the sentence has to be read across them, and the bracketed letters are the ones the scan has lost)", "not_counted_why": "", "note": "The scan is interleaved but both 'is hot and dry in the' and 'second Degree' are legible; nothing has been reconstructed beyond joining those two fragments, and the loss is stated here.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}, {"agreement": "Shown for context. The Chinese yi mu cao is Leonurus japonicus, not the stored Leonurus cardiaca, and the record's own notes field says the same. Shown, not counted. It is also worth seeing that the Chinese entry splits the seed (slightly warm) from the stem and leaf (cold).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "氣味辛甘微温無毒}}{{SKnotes|别録曰甘微寒時珍曰甘辛温}} … 莖葉氣味{{SKnotes|藏器曰寒時珍曰莖葉味辛微苦花味微苦甘根味甘並無毒}}", "gloss": "Chong wei (yi mu cao): the SEED is pungent, sweet, slightly WARM, not toxic, with the Mingyi Bielu calling it sweet and slightly cold and Li Shizhen sweet, pungent and warm. For the STEM AND LEAF, Chen Zangqi says COLD.", "locator": "卷十五 草之四, 茺蔚 (益母), 氣味 and 莖葉氣味", "not_counted_why": "The Chinese yi mu cao is Leonurus japonicus, not the stored Leonurus cardiaca, and the record's own notes field says the same. Shown, not counted. It is also worth seeing that the Chinese entry splits the seed (slightly warm) from the stem and leaf (cold).", "note": "The Chinese yi mu cao is Leonurus japonicus, not the stored Leonurus cardiaca, and the record's own notes field says the same. Shown, not counted. It is also worth seeing that the Chinese entry splits the seed (slightly warm) from the stem and leaf (cold).", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

