insert into _energetics_batch4 values ('H040', $j${"agreement_state": "agree", "app_value": {"moisture": "Dry", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Warm (clear modern value; old sources agree)"}, "batch": 4, "checked_no_reading": ["Bhavaprakasha, Rajanighantu, Shennong Bencao Jing, Bencao Congxin: no Artemisia vulgaris entry found", "Salmon, the chapter 'Of MUGWORT Sea' (Artemisia marina, OCR offset 4037233) is a different species and is reported as cold and dry in the first degree"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Gerard (1633)"}, {"reading": "Dry", "source": "Culpeper (1653)"}, {"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Warm", "source": "Culpeper (1653)"}, {"reading": "Warm", "source": "Salmon (1710)"}]}, "disagreement_text": "", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored parts are leaf and aerial herb, which is what all three English writers describe."], "part_used": "Leaf, Aerial Parts", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Mugwort is hot and dry in the second degree, and somewhat astringent.", "gloss": "Mugwort is hot and dry in the second degree.", "locator": "Book II, Chap. 453 'Of Mugwort', The Temperature", "not_counted_why": "", "note": "", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Artemisia. Mugwort: is hot and dry in the second degree: binding: an herb appropriated to the female sex; it brings down the menses, brings away both birth and placenta, eases pains in the matrix.; and in his degree tables, 'In the second. … Mugwort' among the hot herbs and 'Dry in the second degree. … Mugwort'", "gloss": "Mugwort is hot and dry in the second degree.", "locator": "Catalogue of simples, Herbs, 'Artemisia' (Gutenberg #49513, offset ~845762); Culpeper's degree tables, 'Herbs' (Gutenberg #49513, offset ~950000)", "not_counted_why": "", "note": "", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "IX. The Qualities. Mugwort is hot and dry in the fecond Degree. Aperitve, Abfterfive, Aftringent, Anodyn, Diuretick, Difcuffive, Nephtitick, Hyfterick, and Emmenagogick.", "gloss": "Mugwort is hot and dry in the second degree.", "locator": "Chap. DV 'Of MUGWORT', The Qualities (OCR near offset 4027000; the chapter heading at offset 4026912 reads 'CHAP. DV: of MUGWORT')", "not_counted_why": "", "note": "", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}, {"agreement": "Shown for context. The Chinese ai is Artemisia argyi, not the stored Artemisia vulgaris. Shown, not counted, although it points the same way.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "氣味苦微温無毒}}{{SKnotes|恭曰生寒熟熱元素曰苦温隂中之陽時珍曰苦而辛生温熟熱可升可降陽也}}", "gloss": "Ai ye: bitter, slightly WARM, not toxic. Su Gong adds that fresh it is cold and cooked it is hot; Li Shizhen, that it is bitter and pungent, warm fresh and hot cooked.", "locator": "卷十五 草之四, 艾 (艾葉), 氣味 (heading credited to 别録)", "not_counted_why": "The Chinese ai is Artemisia argyi, not the stored Artemisia vulgaris. Shown, not counted, although it points the same way.", "note": "The Chinese ai is Artemisia argyi, not the stored Artemisia vulgaris. Shown, not counted, although it points the same way.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}], "sources_agree": true, "stored_before": {"moisture": "Dry", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

