insert into _energetics_batch4 values ('H043', $j${"agreement_state": "none", "app_value": {"moisture": "Moist", "temperature": "Neutral"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moist (clear modern value; no pre-1900 source found)", "temperature": "stays Neutral (clear modern value; no pre-1900 source found)"}, "batch": 4, "checked_no_reading": ["Culpeper 1653: no Avena entry in the catalogue of simples and no oats in the degree tables; his OATS chapter is about a different plant", "Rafinesque, Medical Flora Vol. II, AVENA SATIVA: 'Seeds nutritive, demulcent, refrigerant, equal to Barley in fevers as a gruel', again the grain and again a virtue rather than a degree", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no Avena sativa entry found"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "No pre-1900 source found for this part. Every old reading describes the grain, and this entry is about the green tops.", "no_pre1900_source_found": false, "notes": ["The old books all read the oat GRAIN. Nothing found before 1900 gives a temperature or a moisture for the green tops or the straw, which is the stored part.", "The stored part is the aerial plant, the milky oat tops and straw. Every pre-1900 reading found is for the GRAIN or the oatmeal, which is a different part, so none of them is counted."], "part_used": "Aerial Parts (milky oat)", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Neutral), so it stays Neutral. Moisture: stored value clear (a definite Moist), so it stays Moist.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. Two reasons not to count it: Gerard is reporting Galen inside the sentence, and the chapter is about the grain, not the green tops.", "assigns_moisture": "Dry", "assigns_temperature": "Cool", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Oats are dry and somewhat cold of temperature, as Galen saith.", "gloss": "Oats are dry and somewhat cold.", "locator": "Book I, Chap. 54 'Of Oats', The Nature", "not_counted_why": "Two reasons not to count it: Gerard is reporting Galen inside the sentence, and the chapter is about the grain, not the green tops.", "note": "Two reasons not to count it: Gerard is reporting Galen inside the sentence, and the chapter is about the grain, not the green tops.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "second-hand-report", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Shown for context. Salmon names Galen but then gives his own opinion of the degree, so this is his reading and not only a report. It is still not counted, because the chapter is about the grain and the stored part is the green aerial plant.", "assigns_moisture": "Dry", "assigns_temperature": "Cool", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "X. The Qualities. Oats (according td Galen) are cold and dry, and acording.to our Opinion in the beginning of the firft Degree, Abfterfive, Aftringent and Nutritive.", "gloss": "Oats are cold and dry, and in Salmon's own opinion in the beginning of the first degree.", "locator": "Chap. DXXV 'Of OATS Manured and Wild', The Qualities (OCR near offset 4262500)", "not_counted_why": "Salmon names Galen but then gives his own opinion of the degree, so this is his reading and not only a report. It is still not counted, because the chapter is about the grain and the stored part is the green aerial plant.", "note": "Salmon names Galen but then gives his own opinion of the degree, so this is his reading and not only a report. It is still not counted, because the chapter is about the grain and the stored part is the green aerial plant.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}, {"agreement": "Shown for context. 'Refrigerans', cooling, is a virtue and not a felt temperature, and the entry is for the hulled grain. Shown, not counted.", "assigns_moisture": null, "assigns_temperature": "Cool", "corpus": "american", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "AVENA sativa … QVAL. farinacea, insipida. Vsitatissima. vis : refrigerans magis, quam Hordeum. vsvs: Febres.", "gloss": "Quality: mealy, tasteless. Virtue: cooling, more so than barley. Use: fevers.", "locator": "No. 23, AVENA sativa", "not_counted_why": "'Refrigerans', cooling, is a virtue and not a felt temperature, and the entry is for the hulled grain. Shown, not counted.", "note": "'Refrigerans', cooling, is a virtue and not a felt temperature, and the entry is for the hulled grain. Shown, not counted.", "short": "Schöpf (1787)", "source": "J. D. Schöpf, Materia Medica Americana", "tier": "first-hand", "tradition": "American", "url": "https://archive.org/download/materiamedicaame00scho/materiamedicaame00scho_djvu.txt", "year": "1787"}], "sources_agree": false, "stored_before": {"moisture": "Moist", "temperature": "Neutral"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist"}, "temperature": {"status": "clear", "why": "a definite Neutral"}}}$j$::jsonb);

