-- H046 Peppermint (4 sources, shown, none counted)
insert into _energetics_batch4 values ('H046', $j${"agreement_state": "none", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; no pre-1900 source found)"}, "batch": 4, "checked_no_reading": ["Searched Salmon's Botanologia (1710) for 'peppermint' in every spelling: no chapter and no mention", "Bhavaprakasha, Rajanighantu, Shennong Bencao Jing, Bencao Congxin: no Mentha x piperita entry found"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "No pre-1900 source found for this exact plant. The old books speak of mint as a group, or describe spearmint or the Chinese mint, and peppermint is none of those.", "no_pre1900_source_found": false, "notes": ["No first-hand pre-1900 reading was found for peppermint itself. Everything below is either a statement about mint as a group or a reading for a different species of mint.", "The stored plant is peppermint, Mentha x piperita, a hybrid that was not distinguished from the other mints until the 1690s, after Gerard and Culpeper wrote. None of the books read for this batch has a peppermint chapter."], "part_used": "Leaf", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. A statement about 'mint' as a whole group, which the counting rules set aside as context. Gerard's chapter covers the garden mints and has no peppermint.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Mint is hot and dry in the third degree. It is, saith Galen, somewhat bitter and harsh, and it is inferior to Calamint.", "gloss": "Mint is hot and dry in the third degree.", "locator": "Book II, Chap. 226 'Of Mints', The Temperature", "not_counted_why": "A statement about 'mint' as a whole group, which the counting rules set aside as context. Gerard's chapter covers the garden mints and has no peppermint.", "note": "A statement about 'mint' as a whole group, which the counting rules set aside as context. Gerard's chapter covers the garden mints and has no peppermint.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Shown for context. Culpeper names the species, and it is spearmint, Mentha spicata, one of peppermint's parents but not peppermint. His degree tables list 'Mints' as a group, which is set aside as well.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Mentha sativa. Garden Mints, Spear Mints. Are hot and dry in the third degree, provoke hunger, are wholesome for the stomach, stay vomiting, stop the menses", "gloss": "Garden mint or spearmint is hot and dry in the third degree.", "locator": "Catalogue of simples, Herbs, 'Mentha sativa' (Gutenberg #49513, offset ~881142)", "not_counted_why": "Culpeper names the species, and it is spearmint, Mentha spicata, one of peppermint's parents but not peppermint. His degree tables list 'Mints' as a group, which is set aside as well.", "note": "Culpeper names the species, and it is spearmint, Mentha spicata, one of peppermint's parents but not peppermint. His degree tables list 'Mints' as a group, which is set aside as well.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Shown for context. Salmon's chapter is the garden mint and the sentence is about 'mint' generally. Searching the whole of Botanologia for 'peppermint' in any spelling returns nothing.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "XI. The Qualities. Mint is hot and dry in the third Degree; Aperitive, Abfterfive, Aftringent, Anodyn, Carminative, Digeftive, Difcuffive, Diuretick", "gloss": "Mint is hot and dry in the third degree.", "locator": "Chapter 'Of MINT Garden', The Qualities (OCR at offset 3912007)", "not_counted_why": "Salmon's chapter is the garden mint and the sentence is about 'mint' generally. Searching the whole of Botanologia for 'peppermint' in any spelling returns nothing.", "note": "Salmon's chapter is the garden mint and the sentence is about 'mint' generally. Searching the whole of Botanologia for 'peppermint' in any spelling returns nothing.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}, {"agreement": "Shown for context. The Chinese bo he is Mentha haplocalyx, not Mentha x piperita. Shown, not counted. It is worth seeing that the Chinese entry itself carries three readings, warm, neutral and cool.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "莖葉氣味辛温無毒}}{{SKnotes|思邈曰苦辛平元素曰辛凉}}主治賊風傷寒發汗惡氣心腹脹滿霍亂宿食不消下氣", "gloss": "Bo he, stem and leaf: pungent, WARM, not toxic; Sun Simiao says bitter, pungent and NEUTRAL, Zhang Yuansu says pungent and COOL. For thief wind and cold damage, promotes sweat, for fullness of the heart and belly.", "locator": "卷十四 草之三, 薄荷, 莖葉氣味", "not_counted_why": "The Chinese bo he is Mentha haplocalyx, not Mentha x piperita. Shown, not counted. It is worth seeing that the Chinese entry itself carries three readings, warm, neutral and cool.", "note": "The Chinese bo he is Mentha haplocalyx, not Mentha x piperita. Shown, not counted. It is worth seeing that the Chinese entry itself carries three readings, warm, neutral and cool.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H047 Plantain (4 sources, SOURCES DISAGREE)
insert into _energetics_batch4 values ('H047', $j${"agreement_state": "disagree", "app_value": {"moisture": "Moist", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moist (clear modern value; old sources disagree, shown on page)", "temperature": "stays Cool (clear modern value; old sources agree)"}, "batch": 4, "checked_no_reading": ["Culpeper's PLANTAIN chapter: virtues at length, no degree", "Bhavaprakasha, Rajanighantu: no Plantago major entry found", "Bencao Congxin: the che qian entry follows the Bencao Gangmu and is the same Chinese species"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Culpeper (1653)"}, {"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Cool", "source": "Culpeper (1653)"}, {"reading": "Cool", "source": "Salmon (1710)"}]}, "disagreement_text": "On moisture, Culpeper (1653) and Salmon (1710) read it as dry. The app keeps moist, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored parts are leaf and seed, and Culpeper and Salmon both give the degree for the herb."], "part_used": "Leaf, Seed", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Moist), so it stays Moist.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (cool); differs from the app moisture (source dry, app moist).", "assigns_moisture": "Dry", "assigns_temperature": "Cool", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Plantago. Plantain. Cold and dry; an herb, though common, yet let none despise it, for the decoction of it prevails mightily against tormenting pains and excoriations of the entrails, bloody fluxes, it stops the menses, and spitting of blood … Tragus, Dioscorides.; and in his degree tables, 'Cold in the second degree. … Plantain' and 'Dry in the second degree. … Plantain'", "gloss": "Plantain is cold and dry, and by his tables cold and dry in the second degree.", "locator": "Catalogue of simples, Herbs, 'Plantago' (Gutenberg #49513, offset ~887412); Culpeper's degree tables, 'Herbs' (Gutenberg #49513, offset ~950000)", "not_counted_why": "", "note": "The entry ends with the authorities 'Tragus, Dioscorides' in italics, which the batch 3 default treats as Culpeper's reference rather than as a report, so this is counted.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: agrees with the app temperature (cool); differs from the app moisture (source dry, app moist).", "assigns_moisture": "Dry", "assigns_temperature": "Cool", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "IX. The Qualities. Plantain is coldand dry in the end of the firft Degree, Gerard fays in the fecond Degree. It is dry without biting, and cold without benumming: the Root is faid to be dry in the fame Degree, but not fo cold as the Leaves.", "gloss": "Plantain is cold and dry at the end of the first degree, though Gerard says the second.", "locator": "Chapter 'Of PLANTAIN', The Qualities (OCR at offset 4675992)", "not_counted_why": "", "note": "Salmon gives his own degree and then notes where Gerard differs, so the reading is his.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}, {"agreement": "Shown for context. Gerard names Galen inside the sentence and the rest of the paragraph works out what Galen said, so it is a report and is not counted.", "assigns_moisture": "Dry", "assigns_temperature": "Cool", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Plantain (as Galen saith) is of a mixed temperature; for it hath in it a certain watery coldness, with a little harshness, earthy, dry, and cold: therefore they are cold and dry in the second degree. To be brief, they are dry without biting, and cold without benumbing.", "gloss": "Plantain is cold and dry in the second degree.", "locator": "Book II, Chap. 97 'Of Land Plantain', The Temperature", "not_counted_why": "Gerard names Galen inside the sentence and the rest of the paragraph works out what Galen said, so it is a report and is not counted.", "note": "Gerard names Galen inside the sentence and the rest of the paragraph works out what Galen said, so it is a report and is not counted.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "second-hand-report", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Shown for context. The Chinese che qian is Plantago asiatica and Plantago depressa, not the stored Plantago major, and the heading repeats the Shennong Bencao Jing. Shown, not counted on both grounds.", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "氣味甘寒無毒}}{{SKnotes|别録曰鹹權曰甘平大明曰常山為之使}}主治氣癃止痛利水道小便除濕痺久服輕身耐老", "gloss": "Che qian zi (plantain seed): sweet, COLD, not toxic. For dribbling urine, stops pain, opens the water passages, removes damp painful obstruction.", "locator": "卷十六 草之五, 車前, 氣味 (heading credited to 本經)", "not_counted_why": "The Chinese che qian is Plantago asiatica and Plantago depressa, not the stored Plantago major, and the heading repeats the Shennong Bencao Jing. Shown, not counted on both grounds.", "note": "The Chinese che qian is Plantago asiatica and Plantago depressa, not the stored Plantago major, and the heading repeats the Shennong Bencao Jing. Shown, not counted on both grounds.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}], "sources_agree": false, "stored_before": {"moisture": "Moist", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H048 Raspberry Leaf (2 sources, shown, none counted)
insert into _energetics_batch4 values ('H048', $j${"agreement_state": "none", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; no pre-1900 source found)"}, "batch": 4, "checked_no_reading": ["Culpeper 1653, catalogue of simples: 'Rubus Idæus: Raspis, Raspberries, or Hind-berries: I know no great virtues in the leaves.' No degree, and the leaves expressly dismissed", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no Rubus idaeus entry found"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_counted_source_line": "No pre-1900 source found for this reading. One old writer only supposes it, by comparison to the bramble, and the other page is too damaged in the scan to read.", "no_pre1900_source_found": false, "notes": ["No first-hand pre-1900 reading was found that can be counted for the raspberry LEAF.", "The stored part is the leaf. Both old readings below fail on the part: Gerard's is a hedged comparison with the bramble, and the one sentence in Salmon that carries a degree has lost the words that say which parts it covers."], "part_used": "Leaf", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. A reading by cross-reference would normally count, but this one is hedged twice over: 'is thought to be' like the bramble, and then 'not so much' drying as the bramble, which leaves no degree of its own. The bramble statement it points to gives a moisture and no temperature. Shown, not counted.", "assigns_moisture": "Dry", "assigns_temperature": null, "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "The Raspis is thought to be like the Bramble in temperature and virtues, but not so much binding or drying. The Raspis, saith Dioscorides, performeth those things which the Bramble doth.", "gloss": "The raspberry is thought to be like the bramble in temperature, but less binding and drying. Gerard's bramble paragraph says the buds, flowers, leaves and unripe fruit 'do very much dry and bind withal', and gives no heat or cold.", "locator": "Book III, Chap. 4 'Of the Bramble or Blackberry bush', The Temperature and Virtues, paragraph K", "not_counted_why": "A reading by cross-reference would normally count, but this one is hedged twice over: 'is thought to be' like the bramble, and then 'not so much' drying as the bramble, which leaves no degree of its own. The bramble statement it points to gives a moisture and no temperature. Shown, not counted.", "note": "A reading by cross-reference would normally count, but this one is hedged twice over: 'is thought to be' like the bramble, and then 'not so much' drying as the bramble, which leaves no degree of its own. The bramble statement it points to gives a moisture and no temperature. Shown, not counted.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Shown for context. The page is printed in two columns and the scan has interleaved them: the Qualities heading and the opening of the sentence, which is where the list of parts would stand, are gone. The degree itself is legible, but it cannot be shown that the LEAF, the stored part, is among the parts it covers. Reported as damaged; nothing is reconstructed.", "assigns_moisture": "Dry", "assigns_temperature": "Cool", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "… Flowers, and unripe Fruit are cold and drying in the firft Degree, Af[tringent] …", "gloss": "Flowers and unripe fruit, and whatever else the lost words named, are cold and drying in the first degree.", "locator": "Chapter 'Of RASPBERRY' (Rubus Idaeus vulgaris), The Qualities (OCR near offset 4984100; the chapter number is not legible)", "not_counted_why": "The page is printed in two columns and the scan has interleaved them: the Qualities heading and the opening of the sentence, which is where the list of parts would stand, are gone. The degree itself is legible, but it cannot be shown that the LEAF, the stored part, is among the parts it covers. Reported as damaged; nothing is reconstructed.", "note": "The page is printed in two columns and the scan has interleaved them: the Qualities heading and the opening of the sentence, which is where the list of parts would stand, are gone. The degree itself is legible, but it cannot be shown that the LEAF, the stored part, is among the parts it covers. Reported as damaged; nothing is reconstructed.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H049 Red Clover (2 sources, SOURCES DISAGREE)
insert into _energetics_batch4 values ('H049', $j${"agreement_state": "disagree", "app_value": {"moisture": "Moist", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moist (clear modern value; old sources disagree, shown on page)", "temperature": "stays Cool (clear modern value; old sources agree)"}, "batch": 4, "checked_no_reading": ["Salmon, Botanologia (1710), the chapter 'Of CLAVER-GRASS' (OCR offset 1127301): the chapter is Medicago, the snail clavers and Saint Foin, not Trifolium pratense, and its 'hot and dry in the third Degree' belongs to that plant", "Salmon's other trefoil chapters read for this batch cover the strawberry trefoil, the pease trefoil and the like, not the meadow trefoil", "Bencao Gangmu, Bencao Congxin, Shennong Bencao Jing, Bhavaprakasha, Rajanighantu: no Trifolium pratense entry found"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Gerard (1633)"}, {"reading": "Dry", "source": "Culpeper (1653)"}], "temperature": [{"reading": "Cool", "source": "Gerard (1633)"}, {"reading": "Cool", "source": "Culpeper (1653)"}]}, "disagreement_text": "On moisture, Gerard (1633) and Culpeper (1653) read it as dry. The app keeps moist, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the flower, and Gerard's reading is expressly for the leaves and flowers."], "part_used": "Flower", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Moist), so it stays Moist.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (cool); differs from the app moisture (source dry, app moist).", "assigns_moisture": "Dry", "assigns_temperature": "Cool", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "The leaves and flowers of Meadow Trefoils are cold and dry.", "gloss": "The leaves and flowers of meadow trefoil are cold and dry.", "locator": "Book II, Chap. 494 'Of Three-Leaved Grass, or Meadow Trefoil', The Temperature", "not_counted_why": "", "note": "The chapter is the meadow trefoil, which is the red clover of the stored row, and the reading names the flower, the stored part.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: agrees with the app temperature (cool); differs from the app moisture (source dry, app moist).", "assigns_moisture": "Dry", "assigns_temperature": "Cool", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Trifolium. Trefoil: dry in the third degree, and cold: The ordinary Meadow Trefoil, cleanses the bowels of slimy humours that stick to them, being used either in drinks or clysters; outwardly they take away inflammations.", "gloss": "Trefoil is dry in the third degree and cold; the entry then speaks of the ordinary meadow trefoil.", "locator": "Catalogue of simples, Herbs, 'Trifolium' (Gutenberg #49513, offset ~898445)", "not_counted_why": "", "note": "Counted, because the entry itself goes on to name the ordinary meadow trefoil. It should be seen that the degree tables in the same book contradict it: they put Trefoil among the 'Herbs temperate in respect of heat' and among the herbs 'Dry in the third degree'. The dryness matches, the temperature does not, and only this entry is counted so that Culpeper does not vote twice.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}], "sources_agree": false, "stored_before": {"moisture": "Moist", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H050 Reishi (3 sources, SOURCES DISAGREE)
insert into _energetics_batch4 values ('H050', $j${"agreement_state": "disagree", "app_value": {"moisture": "Neutral", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Neutral (clear modern value; no pre-1900 source found)", "temperature": "stays Warm (clear modern value; old sources disagree, shown on page)"}, "batch": 4, "checked_no_reading": ["Bencao Gangmu, the other four of the six zhi (qing, huang, bai, hei): all given as ping, neutral, and all copied from the Shennong Bencao Jing; none of them is the red zhi", "Bencao Congxin (1757) and Porter Smith (1871): no zhi entry found", "Culpeper 1653, Gerard 1633, Salmon 1710, Bhavaprakasha, Rajanighantu, Dymock, Dutt, Ibn al-Baytar: no entry"], "counted_readings": {"moisture": [], "temperature": [{"reading": "Neutral", "source": "Shennong Bencao Jing (c. 200 CE)"}]}, "disagreement_text": "On temperature, Shennong Bencao Jing (c. 200 CE) reads it as neutral. The app keeps warm, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_counted_source_line": "", "no_pre1900_source_found": false, "notes": ["The stored part is the fruiting body, which is what the Chinese books mean by zhi."], "part_used": "Fruiting Body", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm), so it stays Warm. Moisture: stored value clear (a definite Neutral), so it stays Neutral.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source neutral, app warm).", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "==赤芝==味苦，平。主胸中結，益心氣，補中，增智慧，不忘。久食，輕身、不老、延年、神仙。一名丹芝。", "gloss": "Red zhi (chi zhi): bitter, NEUTRAL (ping). For binding in the chest, benefits the heart qi, supplements the centre, increases wisdom, prevents forgetting. Eaten long it lightens the body. Also called dan zhi.", "locator": "上經 (upper class), 赤芝", "not_counted_why": "", "note": "Chi zhi, the red zhi, is the entry the lingzhi drug descends from and is the one identified today with Ganoderma lucidum. The identification rests on that tradition rather than on a botanical name, which is flagged in the doc.", "short": "Shennong Bencao Jing (c. 200 CE)", "source": "神農本草經 (Shennong Bencao Jing, c. 200 CE), Sun Xingyan recension", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/神農本草經_(孫星衍)", "year": "c. 200 CE (recension 1799)"}, {"agreement": "Shown for context. The entry repeats the Shennong reading word for word and credits it, so it counts once and is credited to Shennong.", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "赤芝一名丹芝{{SKnotes|本經}}氣味苦平無毒主治胸中結益心氣補中増智慧不忘久食輕身不老延年神仙{{SKnotes|本經}}", "gloss": "Red zhi, also called dan zhi: bitter, neutral, not toxic (credited to the Shennong Bencao Jing).", "locator": "卷二十八 菜之五, 芝 (芝栭類), 赤芝", "not_counted_why": "The entry repeats the Shennong reading word for word and credits it, so it counts once and is credited to Shennong.", "note": "The entry repeats the Shennong reading word for word and credits it, so it counts once and is credited to Shennong.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}, {"agreement": "Shown for context. Zi zhi, the purple zhi, is taken today to be Ganoderma sinense, a different species from the stored Ganoderma lucidum. Shown, not counted. It is the one old reading that points the way the stored Warm does.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "紫芝一名木芝{{SKnotes|本經}}氣味甘温無毒{{SKnotes|甄權曰平}}主治耳聾利闗節保神益精氣堅筋骨好顔色久服輕身不老延年", "gloss": "Purple zhi (zi zhi), also called mu zhi: sweet, WARM, not toxic; Zhen Quan says neutral. For deafness, frees the joints, guards the spirit, benefits essence and qi.", "locator": "卷二十八 菜之五, 芝, 紫芝", "not_counted_why": "Zi zhi, the purple zhi, is taken today to be Ganoderma sinense, a different species from the stored Ganoderma lucidum. Shown, not counted. It is the one old reading that points the way the stored Warm does.", "note": "Zi zhi, the purple zhi, is taken today to be Ganoderma sinense, a different species from the stored Ganoderma lucidum. Shown, not counted. It is the one old reading that points the way the stored Warm does.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}], "sources_agree": false, "stored_before": {"moisture": "Neutral", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Neutral"}, "temperature": {"status": "clear", "why": "a definite Warm"}}}$j$::jsonb);

do $do$
declare
  rec record;
  n int;
  written int := 0;
  skipped int := 0;
begin
  for rec in select herb_id, citation from _energetics_batch4 order by herb_id loop
    update public.herbs h
       set energetics_citation = rec.citation,
           last_updated = now()
     where h.herb_id = rec.herb_id
       and h.energetics_citation is distinct from rec.citation
       and (h.energetics_citation is null or h.energetics_citation ? 'batch');
    get diagnostics n = row_count;
    if n = 1 then
      written := written + 1;
    else
      if exists (select 1 from public.herbs
                  where herb_id = rec.herb_id and energetics_citation = rec.citation) then
        skipped := skipped + 1;
      else
        raise exception '%.energetics_citation: live value is neither NULL nor a batch object (or the herb is missing); not overwritten', rec.herb_id;
      end if;
    end if;
  end loop;
  raise notice 'energetics batch 4: %s written, %s already current', written, skipped;
end
$do$;

-- -----------------------------------------------------------------------------
-- 2. Verification. Any failure aborts the whole transaction.
-- -----------------------------------------------------------------------------
do $do$
declare
  bad text[] := '{}';
  n int;
  moved text;
begin
  select count(*) into n from public.herbs where (energetics_citation->>'batch')::int = 4;
  if n <> 25 then bad := bad || ('batch 4 herbs: ' || n || ', expected 25'); end if;
  select count(*) into n from public.herbs where energetics_citation ? 'batch';
  if n <> 100 then bad := bad || ('batch citations in total: ' || n || ', expected 100'); end if;
  select count(*) into n from public.herbs
   where energetics_citation is not null and not (energetics_citation ? 'batch');
  if n <> 69 then bad := bad || ('legacy single-source citations: ' || n || ', expected 69'); end if;

  -- Every batch herb has a sources array or the honest no-source flag, and every
  -- stored source carries the fields the page renders.
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and (jsonb_typeof(energetics_citation->'sources') = 'array'
          or (energetics_citation->>'no_pre1900_source_found')::boolean);
  if n <> 100 then bad := bad || ('batch herbs with a sources array or the no-source flag: ' || n || ', expected 100'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and jsonb_array_length(coalesce(energetics_citation->'sources', '[]'::jsonb)) = 0
     and not (energetics_citation->>'no_pre1900_source_found')::boolean;
  if n <> 0 then bad := bad || (n || ' herb(s) have no source and no no-source flag'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch' and coalesce(energetics_citation->>'rule', '') = '';
  if n <> 0 then bad := bad || (n || ' herb(s) carry no basis line'); end if;
  select count(*) into n
    from public.herbs h,
         lateral jsonb_array_elements(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) s
   where h.energetics_citation ? 'batch';
  if n <> 256 then bad := bad || ('stored sources: ' || n || ', expected 256'); end if;
  select count(*) into n
    from public.herbs h,
         lateral jsonb_array_elements(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) s
   where h.energetics_citation ? 'batch'
     and not (s ? 'source' and s ? 'year' and s ? 'corpus' and s ? 'tier'
              and s ? 'assigns_temperature' and s ? 'assigns_moisture'
              and s ? 'excerpt' and s ? 'locator' and s ? 'url'
              and s ? 'agreement' and s ? 'counted');
  if n <> 0 then bad := bad || (n || ' source(s) are missing a required field'); end if;
  select count(*) into n
    from public.herbs h,
         lateral jsonb_array_elements(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) s
   where h.energetics_citation ? 'batch'
     and not (s->>'counted')::boolean
     and coalesce(s->>'not_counted_why', '') = '';
  if n <> 0 then bad := bad || (n || ' uncounted source(s) do not say why they were not counted'); end if;

  -- Never claim agreement the data does not carry.
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and energetics_citation->>'agreement_state' = 'disagree'
     and coalesce(energetics_citation->>'disagreement_text', '') = '';
  if n <> 0 then bad := bad || (n || ' disagreeing herb(s) carry no disagreement sentence'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and (energetics_citation->>'sources_agree')::boolean
     and coalesce(energetics_citation->>'disagreement_text', '') <> '';
  if n <> 0 then bad := bad || (n || ' agreeing herb(s) also carry a disagreement sentence'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and (energetics_citation->>'sources_agree')::boolean
     and jsonb_array_length(coalesce(energetics_citation->'sources', '[]'::jsonb)) = 0;
  if n <> 0 then bad := bad || (n || ' herb(s) claim agreement with no sources at all'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and energetics_citation->>'disagreement_text' like '%' || chr(8212) || '%';
  if n <> 0 then bad := bad || (n || ' disagreement sentence(s) contain an em dash'); end if;

  -- Sources found but none counted: the herb must say why, and a herb that DID
  -- count a source must never carry that line.
  select count(*) into n from public.herbs h
   where h.energetics_citation ? 'batch'
     and jsonb_array_length(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) > 0
     and not exists (select 1 from jsonb_array_elements(h.energetics_citation->'sources') s
                      where (s->>'counted')::boolean);
  if n <> 12 then bad := bad || ('herbs with sources but none counted: ' || n || ', expected 12'); end if;
  select count(*) into n from public.herbs h
   where h.energetics_citation ? 'batch'
     and jsonb_array_length(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) > 0
     and not exists (select 1 from jsonb_array_elements(h.energetics_citation->'sources') s
                      where (s->>'counted')::boolean)
     and coalesce(h.energetics_citation->>'no_counted_source_line', '') = '';
  if n <> 0 then bad := bad || (n || ' herb(s) counted no source and say nothing about why'); end if;
  select count(*) into n from public.herbs h
   where h.energetics_citation ? 'batch'
     and coalesce(h.energetics_citation->>'no_counted_source_line', '') <> ''
     and exists (select 1 from jsonb_array_elements(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) s
                  where (s->>'counted')::boolean);
  if n <> 0 then bad := bad || (n || ' herb(s) claim no counted source while showing one'); end if;

  -- 3. This batch changes NO app value. Nothing may have moved.
  select count(*), string_agg(h.herb_id, ', ' order by h.herb_id) into n, moved
    from public.herbs h join _energetics_before_b4 b using (herb_id)
   where h.temperature is distinct from b.temperature
      or h.moisture is distinct from b.moisture;
  if n <> 0 then
    bad := bad || ('energetics moved on ' || n || ' herb(s): ' || coalesce(moved, 'none') || '; this batch must move none');
  end if;
  select count(*) into n from public.herbs;
  if n <> (select count(*) from _energetics_before_b4) then
    bad := bad || 'the herb count changed'::text;
  end if;
  select count(*) into n from public.herb_energetics_evidence_v;
  if n <> 100 then bad := bad || ('herb_energetics_evidence_v rows: ' || n || ', expected 100'); end if;

  if array_length(bad, 1) is not null then
    raise exception 'energetics batch 4: checks failed: %s', array_to_string(bad, '; ');
  end if;
end
$do$;

-- 4. The tier gate, proved by READING the view as anon rather than by reading its
--    definition. A blind check that returns nothing looks healthy, so this asserts
--    a NON-EMPTY free result and a NULL source list together.
do $do$
declare
  bad text[] := '{}';
  free_text text;
  src jsonb;
  seen int;
begin
  begin
    set local role anon;
  exception when insufficient_privilege then
    raise notice 'cannot SET ROLE anon here; the functional tier check was skipped';
    return;
  end;
  select count(*) into seen from public.herb_energetics_evidence_v;
  if seen <> 100 then bad := bad || ('anon sees ' || seen || ' evidence rows, expected 100'); end if;
  select disagreement_text, sources into free_text, src
    from public.herb_energetics_evidence_v where herb_id = 'H028';
  if coalesce(free_text, '') = '' then
    bad := bad || 'anon cannot read the disagreement sentence on H028'::text;
  end if;
  if src is not null then
    bad := bad || 'anon can read the Root source list on H028'::text;
  end if;
  select no_counted_source_line into free_text
    from public.herb_energetics_evidence_v where herb_id = 'H026';
  if coalesce(free_text, '') = '' then
    bad := bad || 'anon cannot read the no-counted-source line on H026'::text;
  end if;
  if (select no_pre1900_source_found from public.herb_energetics_evidence_v
       where herb_id = 'H030') is not true then
    bad := bad || 'anon cannot read the no-source flag on H030'::text;
  end if;
  reset role;
  if array_length(bad, 1) is not null then
    raise exception 'energetics batch 4: tier gate failed: %s', array_to_string(bad, '; ');
  end if;
end
$do$;

commit;
